(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-hospitality'] = AINOW['data/data-hospitality'] || {};

const hospitalityPrompts = [
    {"id":"hsp-1","title":"Hotel Revenue Management Strategy","prompt":"You are a revenue management consultant specializing in independent boutique hotels. Develop a 90-day revenue recovery strategy for a 78-room boutique hotel in Lisbon's Alfama district that is currently running at 61% occupancy with an ADR of €185 (RevPAR €112.85) versus the comp set running at 74% occupancy with ADR €210 (RevPAR €155.40). The hotel's primary booking channels are: direct website (22%), Booking.com (45%), Expedia (18%), and walk-in/phone (15%). The property has no loyalty program, no minimum stay restrictions on weekends, and has not updated its rate structure in 14 months. The strategy should cover: rate structure redesign (BAR ladder with 6 rate levels, weekend minimum stay policy, last-minute vs. advance purchase pricing), channel mix optimization (steps to shift 10% from OTAs to direct in 90 days — metasearch investment, rate parity audit, direct booking incentive), demand calendar analysis (identify the next 3 high-demand periods and recommended pricing actions), and one quick win implementable in Week 1 with projected RevPAR impact.","tags":["revenue-management","hotels","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

    {"id":"hsp-2","title":"Guest Experience Journey Mapping","prompt":"Act as a guest experience director at a five-star urban hotel. Map the complete emotional journey of a business traveler from the moment they search for the hotel online to the moment they land back home after checkout. For each of the 12 touchpoints (search, booking confirmation, pre-arrival email, arrival, check-in, in-room first impression, F&B ordering, concierge interaction, sleep quality, checkout, post-stay email, review request), identify: the guest's dominant emotion, the most likely friction point, one signature moment the hotel could own, and the metric used to measure success at that touchpoint. Then prioritize the three touchpoints with the highest ROI for immediate investment and explain why.","tags":["guest-experience","cx","hotels"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":true},

    {"id":"hsp-3","title":"F&B Menu Engineering Analysis","prompt":"You are a food and beverage consultant. Conduct a full menu engineering analysis using the BCG matrix (Stars, Plowhorses, Puzzles, Dogs) for a hotel restaurant. The menu has 32 items across 6 categories. For each quadrant, provide: the recommended merchandising strategy (placement, description rewrite, price adjustment), specific techniques to migrate Puzzle items to Stars (e.g., server scripting, portion adjustment, ingredient swap), a decision framework for discontinuing Dog items without alienating regulars, and a worked example showing how repositioning one Plowhorse item through description rewriting and strategic placement can increase its perceived value by 15-20% without a price change. Include a template for the monthly menu engineering scorecard that tracks contribution margin, popularity index, and trend direction.","tags":["f&b","menu-engineering","restaurant"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":true},

    {"id":"hsp-4","title":"Hotel Crisis Communication Playbook","prompt":"Develop a comprehensive crisis communication playbook for a 250-room full-service hotel. Cover four crisis scenarios in detail: (1) a foodborne illness outbreak affecting 15+ guests, (2) a serious guest injury on property, (3) a social media viral complaint with 500K+ impressions, and (4) a natural disaster requiring partial evacuation. For each scenario provide: the first 60-minute response protocol, the internal notification chain (who calls whom in what order), the holding statement for media within 2 hours, the guest communication script, the social media response sequence, and the post-crisis reputation recovery steps. Also include a one-page crisis readiness self-audit checklist the GM should complete quarterly.","tags":["crisis-management","communications","hotels"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":true},

    {"id":"hsp-5","title":"Luxury Hotel Sustainability Roadmap","prompt":"You are a sustainability consultant working with a 180-room luxury mountain resort. The property currently has no formal sustainability program, generates 2.4 tonnes of waste per month, uses 380 liters of water per occupied room night, and sources 85% of its food from national distributors rather than local farms. Design a 24-month roadmap to achieve Green Key certification. Structure it in three 8-month phases: Phase 1 (Quick wins — LED conversion, linen reuse program, food waste tracking, single-use plastic elimination), Phase 2 (Systems change — solar pre-heating for water, composting partnership, local sourcing target of 40%), Phase 3 (Certification and storytelling — guest-facing communication, staff training, press launch). For each initiative include estimated cost, projected saving, and the staff role responsible.","tags":["sustainability","hotels","operations"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":true},

    {"id":"hsp-6","title":"Restaurant Pre-Opening Checklist","prompt":"You are a restaurant operations consultant. Build a comprehensive 90-day pre-opening master checklist for a 120-cover farm-to-table restaurant. Organize it by workstream: (1) Licenses and compliance — food handler permits, liquor license timeline, health inspection pre-check, fire safety sign-off; (2) Kitchen setup — equipment commissioning schedule, cold chain validation, mise en place standards, staff station assignments; (3) Front of house — POS configuration, reservation system setup, server training schedule, uniform delivery; (4) Menu and recipes — recipe costing for every dish, allergen matrix, staff tasting sessions, supplier contracts signed; (5) Marketing — Google Business profile, Instagram launch content, local press outreach, soft opening invite list. Flag the 5 items most commonly missed that cause opening-day failures and explain how to prevent each.","tags":["restaurant","operations","planning"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

    {"id":"hsp-7","title":"Hotel Digital Marketing Strategy","prompt":"Act as a digital marketing director for an independent 95-room boutique hotel competing against three branded properties in the same market. The hotel currently spends €48,000 per year on marketing with 78% going to OTA commissions and only 8% on direct digital channels. Develop a 12-month digital marketing strategy to increase direct bookings from 19% to 35% of total revenue. Cover: website conversion optimization (5 specific changes to the booking engine flow), Google Hotel Ads setup and bidding strategy, email marketing automation sequences (pre-arrival, in-stay, post-stay, win-back), Instagram and TikTok content strategy with posting cadence, and a metasearch channel plan. Include a month-by-month budget reallocation schedule from OTA spend to owned channels, and define the KPIs and targets for each channel.","tags":["digital-marketing","hotels","direct-bookings"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

    {"id":"hsp-8","title":"Housekeeping Operations Optimization","prompt":"You are a hotel operations consultant. A 210-room full-service hotel is experiencing housekeeping inefficiencies: average room-clean time is 38 minutes (industry benchmark 28 minutes), linen costs are 22% over budget, and guest satisfaction scores for room cleanliness have dropped from 4.6 to 4.1 over the past two quarters. Diagnose the most likely root causes and design a full operations improvement plan. Include: a time-and-motion study protocol for the head housekeeper to run over one week, a room-cleaning sequence optimization (describe the optimal physical movement path through a standard king room), a linen par stock calculation model, a daily quality inspection checklist using the 3-minute audit method, and a staff incentive structure tied to quality scores. Project the cost saving from reaching benchmark clean times across a full year of operations.","tags":["housekeeping","operations","hotels"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

    {"id":"hsp-9","title":"Revenue Management for F&B Outlets","prompt":"Apply revenue management principles — traditionally used for hotel rooms — to a hotel's three F&B outlets: a 90-cover signature restaurant, a 40-seat lobby bar, and a 200-cover poolside café. For each outlet, define: the equivalent of RevPAR (Revenue Per Available Seat Hour — RevPASH), the demand pattern by day-part and day-of-week, table turn time targets and how to achieve them without making guests feel rushed, dynamic pricing opportunities (weekend surcharges, prix-fixe minimums on peak nights, happy hour engineering), and reservation policy recommendations. Also address how to manage the tension between maximizing seat revenue and maintaining the luxury guest experience. Provide a one-page dashboard template for each outlet manager to review daily.","tags":["f&b","revenue-management","restaurant"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

    {"id":"hsp-10","title":"Hotel Loyalty Program Design","prompt":"Design a loyalty program for an independent boutique hotel collection with 8 properties across 4 countries. The collection currently has no loyalty scheme and loses an estimated 40% of repeat guests to branded competitors that offer points programs. The program should avoid the commodity trap of points-per-stay and instead build genuine emotional loyalty. Define: the three membership tiers and their qualifying criteria, the benefits at each tier (emphasize experiential rewards over discounts — e.g., breakfast with the chef, private city tour, early access to new suites), the enrollment mechanism at check-in, the CRM data strategy to personalize each return stay, the email communication cadence, and the technology stack required. Include a 3-year financial model showing the break-even point assuming a 12% improvement in repeat guest rate.","tags":["loyalty","hotels","marketing"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

    {"id":"hsp-11","title":"Food Cost Control Framework","prompt":"You are a food and beverage controller. A 180-cover hotel restaurant is running a food cost percentage of 38% against a budget of 30%. Purchases are €42,000 per month. Build a complete food cost control framework to close the 8-point gap within 90 days. Cover: the recipe costing audit process (walk through the exact steps for costing a dish from raw ingredient purchase price to plate), the daily food cost tracking sheet design, the receiving and storage controls that prevent shrinkage, a variance analysis template that identifies whether overrun is caused by waste, theft, portion inconsistency, or over-purchasing, and a supplier renegotiation script for the top 5 commodity items. Show a worked example where closing the gap from 38% to 30% on €504,000 of annual revenue generates approximately €40,320 in additional profit.","tags":["f&b","food-cost","finance"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":false},

    {"id":"hsp-12","title":"Event Sales Proposal Template","prompt":"Write a complete event sales proposal for a corporate client requesting a 3-day leadership conference for 120 delegates at a 5-star hotel. The proposal should include: an executive summary that speaks to business outcomes not room specifications, a day-by-day programme framework with suggested F&B breaks (avoid the standard Danish pastry cliché — propose something memorable), the AV and technology setup with specific recommendations for hybrid participation of 40 remote delegates, accommodation block with room type breakdown and group rate structure, a sustainability commitment section detailing the hotel's zero-waste conference offering, the contract terms and cancellation policy, and a pricing summary with three package tiers (Essential, Signature, Premium). The proposal should be persuasive and specific enough that the client sees differentiated value versus a branded competitor.","tags":["events","sales","hotels"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

    {"id":"hsp-13","title":"Hotel Technology Stack Audit","prompt":"Act as a hospitality technology consultant. A 160-room independent hotel is using a legacy PMS installed in 2014, a standalone channel manager, a separate POS with no integration to the PMS, no CRM, no guest messaging platform, and no revenue management system. The GM manually updates rates twice per week on each OTA individually. Conduct a technology stack audit and design the ideal integrated technology ecosystem for this property. For each system category (PMS, channel manager, booking engine, RMS, CRM, guest messaging, POS, housekeeping app), recommend a specific vendor suited to independent hotels, explain the integration requirement, estimate the annual cost, and quantify the ROI. Prioritize the implementation sequence and identify which single integration will deliver the fastest return.","tags":["technology","hotels","operations"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

    {"id":"hsp-14","title":"Spa Revenue Optimization Plan","prompt":"You are a spa consultant. A hotel spa with 8 treatment rooms is generating €320,000 in annual revenue against a capacity of €580,000 (55% utilization). The spa is busy Thursday–Sunday but near-empty Monday–Wednesday, and 70% of bookings are from hotel guests with only 30% from the local community. Design a 6-month revenue optimization plan. Cover: weekday demand generation (local membership program, corporate wellness partnerships, afternoon tea and treatment packages), yield management for treatment rooms (the spa equivalent of RevPAR — Revenue Per Available Treatment Hour), upselling protocols for therapists at the start and end of each treatment, retail sales training to increase retail capture rate from the current 4% to 12%, and a social media content strategy to attract the local wellness community. Include a monthly revenue forecast showing the path from €320K to €460K.","tags":["spa","revenue-management","hotels"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

    {"id":"hsp-15","title":"Hospitality Staff Onboarding Program","prompt":"Design a 30-day onboarding program for front-of-house staff at a luxury boutique hotel. The program must go beyond compliance training and product knowledge to genuinely embed the hotel's service philosophy and emotional culture. Structure it as follows: Week 1 — Immersion (stay one night as a guest, shadow every department including kitchen and housekeeping, learn the backstory of the building and the founder's vision), Week 2 — Skill building (complaint handling role-plays, upselling simulation, local knowledge test covering 20 restaurants, 5 hidden gems, 3 transport options), Week 3 — Live floor with buddy system, Week 4 — Independent operation with daily debrief. Define the assessment criteria for signing off a new hire as guest-ready, and design the 90-day check-in conversation template for the department head.","tags":["hr","training","hotels"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

    {"id":"hsp-16","title":"Restaurant Concept Development","prompt":"[Describe the location, size, target market, and any constraints such as budget, existing kitchen, or landlord restrictions for your new restaurant concept.]\n\nAct as a restaurant concept consultant. Based on the context provided, develop a complete restaurant concept including: the positioning statement (one sentence that defines who it is for, what it serves, and why it is different), the name (3 options with rationale), the interior design direction (reference 3 specific mood board elements), the menu architecture (number of sections, price range, hero dish description), the service style and staff personality type to hire for, the brand voice guidelines with 3 sample social media captions, and the financial model assumptions (average check, covers per day, target food cost, target labor cost, break-even monthly revenue). Identify the single biggest risk to the concept and how to mitigate it.","tags":["restaurant","concept","strategy"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

    {"id":"hsp-17","title":"Dynamic Pricing Model for Hotels","prompt":"Build a dynamic pricing decision framework for a 120-room city-center hotel. The framework should give a revenue manager a clear decision tree for setting rates each morning. Define: the 5 data inputs to check daily (pickup pace, competitor rates, demand calendar events, channel booking window, weather for leisure-heavy periods), the rate action triggers at each occupancy threshold (below 40%, 40-60%, 60-75%, 75-85%, above 85%), the BAR ladder design with 8 price points and the conditions for moving between them, the last-minute pricing logic for the 0-48 hour booking window, and the overbooking model with walk policy. Provide a sample completed rate decision log for a fictitious Tuesday showing how all inputs combine to reach a rate recommendation, and explain the reasoning step by step.","tags":["revenue-management","pricing","hotels"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

    {"id":"hsp-18","title":"Cocktail Menu Development","prompt":"Act as a bar consultant and mixologist. Design a complete craft cocktail menu for a rooftop bar at a luxury urban hotel. The menu should have 16 cocktails organized into 4 narrative sections that tell a story about the city the hotel is in. For each cocktail provide: the full name, a 2-sentence poetic menu description, the complete recipe with measurements, the glassware, the garnish and the visual presentation notes, the cost to make, and the suggested selling price. The menu must include: 4 low-ABV options, 2 zero-proof cocktails with the same complexity as the alcoholic options, 2 tableside-prepared cocktails for theatre, and at least 3 cocktails using a locally sourced spirit or ingredient. Also write the bar's brand manifesto (150 words) and the staff training guide for describing the menu narrative to guests.","tags":["f&b","cocktails","luxury"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

    {"id":"hsp-19","title":"Hotel P&L Analysis and Cost Reduction","prompt":"You are a hotel financial controller. A 145-room upscale hotel generated €8.2M in total revenue last year but only €820K in GOP (10% margin) against a budget of €1.48M (18% margin). The shortfall is €660K. The departmental P&Ls show: Rooms department at 68% margin (on budget), F&B at -4% margin (budgeted +12%), Spa at 28% margin (budgeted 35%), and undistributed overheads 22% over budget. Conduct a structured diagnostic. For each underperforming area, identify the 3 most likely cost or revenue drivers creating the variance, explain the analysis steps to confirm which driver is the culprit, and recommend the specific corrective action. Produce a 90-day action plan that realistically recovers €400K of the shortfall, with each action assigned to a department head with a target and a deadline.","tags":["finance","hotels","operations"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":true},

    {"id":"hsp-20","title":"Wellness Tourism Package Design","prompt":"[Describe your property type, location, existing wellness facilities, and the guest profile you are trying to attract with this package.]\n\nDesign a premium wellness tourism package for the property described. The package must go beyond a standard 'spa break' to offer a genuinely transformative guest experience. Include: the package name and 3-sentence marketing description, a detailed 3-night itinerary with morning, afternoon, and evening programming (drawing on local nature, culture, and food), the signature treatment or ritual that is exclusive to this property, the nutritional philosophy behind the F&B offerings and 3 sample dish descriptions, the pre-arrival communication strategy to prepare guests mentally before they arrive, the post-departure follow-up to sustain the wellness benefit at home, and the pricing strategy with value justification. Identify the top 3 wellness trends this package should visibly respond to.","tags":["wellness","tourism","hotels"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

    {"id":"hsp-21","title":"Hotel General Manager Weekly Operating Rhythm","prompt":"Design the complete weekly operating rhythm for a General Manager of a 200-room full-service hotel. Cover every recurring meeting and report review that should happen Monday through Sunday, specifying: the meeting name, duration, attendees, the 3 most important agenda items, and the decision or output expected. Include: the daily 15-minute morning briefing (who attends, what data is on the whiteboard), the weekly revenue strategy meeting (what the RMS report shows, what rate actions are decided), the weekly department head meeting (how to keep it under 45 minutes and action-focused), the monthly financial review cadence, and the biannual staff town hall format. Also define the GM's personal daily non-negotiables: the one walk-through, the one guest conversation, and the one coaching moment that must happen every day regardless of what else is on the calendar.","tags":["operations","management","hotels"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

    {"id":"hsp-22","title":"OTA Ranking Optimization Strategy","prompt":"You are an OTA optimization specialist. A 3-star hotel in a competitive beach market has dropped from position 8 to position 24 on Booking.com over the past 6 months, resulting in a 31% drop in OTA-sourced bookings. Diagnose the most likely causes of rank decline and build a 60-day recovery plan. Cover: the Booking.com visibility algorithm factors (review score weight, cancellation rate impact, availability completeness, last-minute availability, preferred partner status), a review response strategy to bring the average score from 7.4 to 8.0 within 90 days, the inventory and rate parity audit, the Genius program cost-benefit analysis for this property, and the content optimization for photos, amenity tags, and property description. Provide a week-by-week implementation schedule with the single most impactful action each week.","tags":["ota","marketing","hotels"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

    {"id":"hsp-23","title":"Conference and Events Pricing Strategy","prompt":"Develop a comprehensive pricing strategy for the conference and events department of a 4-star hotel with 12 meeting rooms ranging from a 6-person boardroom to a 500-person ballroom. The department generates €1.8M per year but has no formal pricing logic — rates are set by the sales team on a case-by-case basis, leading to margin inconsistency. Build: the day delegate rate (DDR) architecture with 3 tiers and what is included at each, the residential conference package structure, the AV and tech pricing menu, the F&B minimum spend logic by room type and day-part, the discount authority matrix (what the sales executive can discount versus what requires GM sign-off), and the value-based selling script for moving a client from the lowest to the middle tier. Include a margin calculator template the sales team can use during the quoting process.","tags":["events","pricing","hotels"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

    {"id":"hsp-24","title":"Seasonal Menu Development Framework","prompt":"Act as an executive chef. Build a complete seasonal menu development framework for a hotel restaurant that changes its menu four times per year. The framework should cover: the menu development calendar (when to start R&D, when to do staff tastings, when to brief the printing company, when to update the website), the supplier engagement process for identifying peak-season ingredients 6 weeks in advance, the recipe development and costing protocol for new dishes, the allergen review and kitchen briefing process, the server training session structure for menu launch week (focus on storytelling and upselling confidence, not just ingredient recitation), and the post-launch review at 30 days (what data signals tell you a new dish is a Star vs. a Dog). Provide a worked example of a complete spring menu with 5 starters, 6 mains, and 4 desserts, each with a menu description written in the voice of the restaurant.","tags":["f&b","menu","restaurant"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

    {"id":"hsp-25","title":"Guest Complaint Resolution Training","prompt":"Design a full-day training workshop on guest complaint resolution for hotel front-of-house staff. The workshop should cover theory and intensive practical role-play. Content outline: Module 1 (90 min) — The psychology of complaint: why guests complain, why most don't, and the lifetime value of a recovered guest versus a lost one. Module 2 (90 min) — The LEARN framework (Listen, Empathize, Apologize, Resolve, Notify) with worked examples for 8 common complaint types. Module 3 (120 min) — Role-play laboratory: 10 scenarios from low-stakes (noisy neighbor) to high-stakes (allegation of staff rudeness). Module 4 (60 min) — Empowerment and escalation: define exactly what each staff grade can offer without manager approval (dollar amounts, upgrades, complimentary items). Include the full facilitator guide, the role-play scenario cards, and the post-training assessment rubric.","tags":["training","guest-experience","hotels"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

    {"id":"hsp-26","title":"Hotel Asset Management Report","prompt":"You are a hotel asset manager preparing a quarterly performance report for the ownership group of a 165-room upscale hotel operating under a management contract. The report covers Q3 of the current year. RevPAR is €142 versus budget €161 (-11.8%) and prior year €138 (+2.9%). TRevPAR is €198 versus budget €225. The management company is attributing the shortfall to 'market softness' but your comp set data shows the market actually grew 3.2% in the same period. Write the full asset manager's report including: the performance narrative with your independent diagnosis of the underperformance, the 5 management accountability areas you are flagging, the specific data requests you are making of the operator, the capital expenditure review (€240K was approved for a lobby refresh — assess whether it is delivering the expected ADR premium), and your recommendations to the ownership group including whether the operator is meeting the performance test threshold in the management agreement.","tags":["finance","hotels","asset-management"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

    {"id":"hsp-27","title":"Destination Wedding Sales Strategy","prompt":"[Describe your property — location, indoor and outdoor ceremony capacity, on-site accommodation, catering capability, and your current wedding revenue and number of events per year.]\n\nDevelop a complete destination wedding sales and marketing strategy for the property described. Include: the ideal client profile (demographics, booking window, budget range, how they search), the lead generation strategy (wedding fair presence, Instagram visual strategy, Google Ads targeting, partnerships with wedding planners), the show-round experience design (the 60-minute property visit that converts), the wedding package architecture (3 tiers with what is included and excluded at each price point), the follow-up email sequence for unconverted enquiries (5 emails over 21 days), the supplier directory of preferred partners and the commercial arrangement with each, and the off-season wedding incentive strategy to fill the calendar in traditionally slow months.","tags":["events","weddings","sales"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

    {"id":"hsp-28","title":"Hotel Food and Beverage Strategy Overhaul","prompt":"A 4-star hotel's F&B operation is losing €380,000 per year. The property has a 140-cover all-day dining restaurant, a 60-seat bar, and a room service operation. Occupancy averages 72%. The restaurant serves 28 covers per day — a 20% seat utilization rate. Room service accounts for 8% of F&B revenue. The bar is profitable but only open until 11 PM. As an F&B strategy consultant, design a complete overhaul. Address: whether to continue operating all three outlets or restructure (apply a zero-based P&L analysis), the concept repositioning of the restaurant to attract both hotel guests and local diners, the pricing strategy to recover margin, the labor model optimization (specifically the challenge of covering breakfast service economically), the room service vs. in-room dining automation trade-off, and the marketing strategy to drive external covers. Provide a year-one financial target and the 6 initiatives that will get you there.","tags":["f&b","strategy","hotels"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

    {"id":"hsp-29","title":"Tourism Destination Branding","prompt":"Act as a destination branding consultant. A coastal region with a population of 120,000 is experiencing a 15% year-on-year decline in tourist arrivals, primarily losing visitors to cheaper Mediterranean destinations. The region has: 6 Blue Flag beaches, a UNESCO-listed old town, a growing craft food and wine scene, and a reputation for being 'boring after 6 PM.' The tourism board has a marketing budget of €800,000. Develop a complete destination rebrand. Include: the brand audit identifying the gap between current perception and the desired positioning, the new destination tagline and brand narrative (the 3-sentence story that makes a traveler feel something), the target visitor persona redefinition (move away from 'everyone' to 2 specific segments with names, descriptions, and media habits), the 12-month marketing plan by channel, the content partnership strategy with micro-influencers versus mass travel media, and the 3-year KPIs for arrivals, spend per visitor, and length of stay.","tags":["tourism","branding","marketing"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

    {"id":"hsp-30","title":"Luxury Hotel Butler Service Standards","prompt":"Design the complete service standards manual for a butler department at a 60-room ultra-luxury hotel where every guest is assigned a personal butler for the duration of their stay. The manual should cover: the butler's pre-arrival preparation protocol (what research is done, what is set up in the room, what the first 30 seconds of the guest relationship must achieve), the anticipatory service matrix (a table mapping guest type — honeymooner, business traveler, family, anniversary couple — to the default behaviors the butler should initiate without being asked), the communication etiquette standards (when to speak, when to remain silent, how to address repeat guests by name naturally), the service recovery authority (what a butler can personally action versus what requires escalation), and the handover protocol between butler shifts so continuity is seamless. Include the butler daily log template and the quality audit checklist used by the Director of Residences.","tags":["luxury","guest-experience","hotels"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":true},

    {"id":"hsp-31","title":"Restaurant Recruitment and Interview Guide","prompt":"You are a restaurant HR manager. Build a complete recruitment and selection guide for hiring a Head Chef for a fine dining restaurant. Include: the job advertisement (write it to attract a chef who values creativity and team culture, not just a CV-builder), the competency framework (6 competencies with behavioral descriptors at four levels), the structured interview guide (10 questions with scoring guidance and the red flags to watch for in each answer), the practical assessment design (what should a candidate cook, in what conditions, and how is it judged — include the scoring rubric), the reference check script focusing on kitchen culture and pressure behavior, and the onboarding plan for the first 90 days including how the new Head Chef should conduct their own team assessment and menu review. Also write the rejection letter that is honest and respectful enough that the candidate feels well treated.","tags":["hr","restaurant","recruitment"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

    {"id":"hsp-32","title":"Hotel Energy Management Program","prompt":"Design a comprehensive energy management program for a 300-room full-service hotel currently spending €1.2M per year on energy (electricity 68%, gas 32%). The hotel has no Building Management System, lighting is a mix of LED and legacy halogen, HVAC is centrally controlled with no room-level occupancy sensing, and laundry is done on-site. Target: reduce energy cost by 25% (€300,000) within 24 months without impacting guest comfort. Structure the program in three phases: Quick wins in months 1-3 (LED conversion completion, hot water thermostat optimization, kitchen equipment scheduling, behavioral campaigns for staff); Systems investment in months 4-12 (BMS installation, occupancy-linked HVAC, heat recovery on laundry); Advanced optimization in months 13-24 (solar PV feasibility, smart metering by department, energy dashboard for department heads). For each initiative include capital cost, payback period, and annual saving.","tags":["sustainability","operations","hotels"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

    {"id":"hsp-33","title":"Hospitality Marketing Campaign for Shoulder Season","prompt":"[Describe your property type, location, your high season and your current shoulder season (specify months, typical occupancy, and the primary reason guests do not visit during this period).]\n\nDevelop a marketing campaign to drive demand during the shoulder season described. The campaign should include: the insight that reframes the shoulder season as a positive (not 'fewer crowds' but a specific compelling narrative), the campaign name and visual concept, the target audience and why they are specifically motivated to travel in this period, the offer architecture (what is included, how it is priced, and the urgency mechanism), the paid media plan (Google Ads, Meta, email to existing database), the PR story pitch to 3 specific media outlets, the influencer brief for one content creator visit, and the landing page structure. Define success metrics at 30, 60, and 90 days and the booking value you need to generate to justify the campaign investment.","tags":["marketing","hotels","seasonality"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

    {"id":"hsp-34","title":"Food Allergen Management System","prompt":"Design a complete food allergen management system for a hotel with three F&B outlets: a fine dining restaurant, an all-day café, and room service. The system must meet the legal requirements for the 14 major allergens and go beyond compliance to genuinely protect guests and build trust. Cover: the supplier information collection process (the allergen questionnaire to send every supplier, the protocol for ingredient substitutions), the recipe management system (how allergen data is recorded, updated, and communicated to the kitchen team), the menu printing and digital menu allergen display standards, the guest communication touchpoints (reservation confirmation question, server script at table, allergy card system in the kitchen), the cross-contamination prevention protocols by station, the staff training assessment (the test every new kitchen staff member must pass before going live), and the incident management protocol if an allergic reaction occurs on property. Include a sample allergen matrix template for a 20-dish menu.","tags":["f&b","safety","compliance"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

    {"id":"hsp-35","title":"Hotel Revenue Management KPI Dashboard","prompt":"Design the complete revenue management KPI dashboard for a 180-room upscale hotel. The dashboard should be usable by the GM and Revenue Manager in the daily morning briefing and should contain all the information needed to make rate and availability decisions for the next 30 days. Define every metric on the dashboard: the formula, the data source, the benchmark, and the action trigger. Include: forward-looking metrics (pickup pace by segment for the next 30 days, lead time distribution, channel booking window analysis), current performance metrics (occupancy, ADR, RevPAR versus budget and prior year, by segment), competitive position metrics (STR comp set index — OCC index, ADR index, RevPAR index), and F&B and ancillary revenue metrics. Also design the weekly displacement analysis template for evaluating whether to accept a group booking that displaces transient business, with a worked numerical example.","tags":["revenue-management","analytics","hotels"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

    {"id":"hsp-36","title":"Independent Restaurant Business Plan","prompt":"[Describe your restaurant concept, proposed location, your background and relevant experience, and your available startup capital.]\n\nWrite a complete business plan for the restaurant concept described. Include: Executive Summary (1 page — concept, target market, unique selling proposition, financial highlights), Market Analysis (local competitive landscape, gap in the market, target customer personas with dining frequency and spend data), Operations Plan (kitchen design philosophy, supplier strategy, opening hours, staffing model for Year 1), Marketing Plan (pre-opening buzz strategy, first 90 days of social media, review platform strategy, local PR), Financial Projections (month-by-month P&L for Year 1, Year 2 and Year 3 summary, break-even analysis, cash flow waterfall), and Risk Analysis (5 key risks with probability, impact, and mitigation). Make the financial projections conservative and show your working for every key assumption.","tags":["restaurant","business-plan","finance"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

    {"id":"hsp-37","title":"Hotel Renovation Project Management","prompt":"You are a hotel project manager. A 95-room independent hotel is planning a phased renovation of all guest rooms while remaining open. The total budget is €2.8M for room refurbishment (€29,500 per room), covering new bathroom tiles and fixtures, furniture replacement, flooring, and redecoration. The renovation must be completed within 14 months without closing the hotel. Design the complete project management framework: the phasing plan (which floors to close and in what sequence, balancing revenue impact against contractor efficiency), the procurement timeline for materials (lead times for Italian tiles, custom furniture, and FF&E), the quality control inspection protocol before each room is returned to service, the communication strategy to manage guest expectations during construction, the contingency budget allocation (typically 12-15% on hotel refurbishments — explain when to invoke it), and the punch list and sign-off process. Include a Gantt chart structure for the 14-month program.","tags":["hotels","renovation","project-management"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

    {"id":"hsp-38","title":"Beverage Program Profitability Analysis","prompt":"Act as a beverage consultant. A 120-cover restaurant is generating €380,000 in beverage revenue per year (wine 55%, spirits 20%, beer 12%, soft drinks and water 8%, cocktails 5%) with an overall beverage cost of 34% against a target of 28%. The 6-point cost overrun represents approximately €22,800 in lost margin annually. Conduct a full beverage program profitability analysis. Identify the likely causes of the overrun (over-pouring, pricing inconsistency, high-cost wine selection, spoilage), build the control framework (the daily yield check for spirits, the bottle-for-bottle exchange system, the wine-by-the-glass pour size and pricing audit), redesign the wine list architecture to improve margin (explain the price point ladder and how to use house wine and private label to anchor the list), and write the server training module on beverage upselling that increases the average spend per cover by €3.50.","tags":["f&b","beverage","finance"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

    {"id":"hsp-39","title":"Corporate Travel Account Management","prompt":"You are a hotel sales manager. A pharmaceutical company with 820 travelling employees and an estimated €1.4M in annual hotel spend in your city has issued an RFP for a preferred hotel agreement. The company's stated priorities are: consistent room availability, flexible cancellation (48-hour policy), meeting room access for ad-hoc bookings, and a corporate rate below €145 per room. Your hotel's standard corporate rate is €162. Design the complete response strategy: the rate you will bid and the commercial logic for that decision, the value-add package that justifies your rate position without simply discounting (free meeting room credits, late checkout guarantee, dedicated account manager), the RFP response document structure, the due diligence questions you need answered before signing (block commitment, blackout dates, attrition clause), and the account management plan for the first year of the contract including quarterly business reviews.","tags":["sales","hotels","corporate"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

    {"id":"hsp-40","title":"Hotel Food Waste Reduction Program","prompt":"Design a zero-waste food program for a hotel with 220 rooms and three F&B outlets that currently sends approximately 1.8 tonnes of food waste to landfill each month at a disposal cost of €2,100. The program should pursue both environmental and financial goals. Include: the waste audit methodology to establish the baseline by waste stream (prep waste, plate waste, spoilage, over-production), the production planning discipline to reduce over-production (the daily cover forecast model and how it drives the prep list), the nose-to-tail and root-to-leaf cooking philosophy applied to the menu design, the staff behavioral change program (the kitchen brigade waste pledge, daily waste weight recording, weekly waste league table), the organic waste diversion strategy (on-site composting, biodigester assessment, partnership with a local urban farm), and the guest-facing storytelling that turns the program into a marketing asset. Project the annual cost saving from reaching a 50% waste reduction target.","tags":["sustainability","f&b","operations"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

    {"id":"hsp-41","title":"Hospitality Recruitment and Retention Strategy","prompt":"[Describe your property type, size, location, current staff turnover rate, primary roles you struggle to fill, and any known reasons staff are leaving.]\n\nDevelop a comprehensive recruitment and retention strategy addressing the challenges described. Include: the employer value proposition (EVP) — the honest, compelling story of why someone should build their career at this property versus a competitor, the recruitment channel mix for the 3 hardest-to-fill roles (be specific: which job boards, which culinary schools, which social platforms, which employee referral incentives), the structured onboarding experience that prevents the 90-day quit (the most dangerous period for new hires), the career pathway framework showing visible progression routes from entry-level to management for 4 key departments, the stay interview template (the conversation to have with high performers every 6 months), the exit interview diagnostic to identify the real reasons people are leaving, and the manager development program that addresses the most common reason staff cite for leaving hospitality — poor immediate supervisor.","tags":["hr","retention","hotels"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

    {"id":"hsp-42","title":"Hotel Group Business Displacement Analysis","prompt":"A conference organizer has submitted an RFP for a 3-night residential conference for 90 delegates at your 140-room hotel. The event dates are Friday to Sunday in August — your highest-demand period of the year. The organizer is requesting a rate of €195 B&B per room per night plus a delegate day rate of €65 for meeting facilities. Your typical transient ADR in August is €245, and the event will require you to hold 90 rooms out of general inventory for 45 days. Conduct a complete displacement analysis. Calculate: the total event revenue across rooms, F&B, and meeting facilities, the transient revenue you are displacing at the expected August occupancy of 88%, the net value of accepting versus declining (factoring in the certainty premium of a confirmed group versus speculative transient), and the counter-proposal you would make to the organizer if the original terms are not acceptable. Provide the decision recommendation and the commercial rationale in language you could present to the owner.","tags":["revenue-management","events","hotels"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

    {"id":"hsp-43","title":"Tasting Menu Development and Costing","prompt":"Act as an executive chef preparing to launch a 9-course tasting menu at a fine dining restaurant priced at €145 per person, with an optional wine pairing at €85. Design the complete menu with: each course name and a 2-sentence poetic description, the key technique showcased in each dish, the primary local or seasonal ingredient, and the plate presentation concept. Then conduct the full food cost analysis: the recipe cost for each course (ingredients only), the total food cost per cover, the food cost percentage, and whether the menu is financially viable at €145. If food cost exceeds 32%, identify which courses to re-engineer and how. Also design the wine pairing: 9 pours with the rationale for each pairing, the pour size, the wine cost per pour, and the total beverage cost percentage for the pairing at €85. Conclude with the server training notes on how to describe and sell the menu at the table.","tags":["f&b","fine-dining","menu"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

    {"id":"hsp-44","title":"Hotel Brand Standards Audit","prompt":"You are a hotel brand consultant. Conduct a brand standards self-audit framework for an independent boutique hotel that is considering joining a soft brand collection. The audit covers the gap between the hotel's current operation and the soft brand's minimum standards. Structure the audit across 8 dimensions: (1) Physical product — room quality, bathroom standards, F&B outlet presentation; (2) Technology — PMS, Wi-Fi speed, smart TV specification; (3) Guest experience — check-in time standards, welcome amenity, wake-up call reliability; (4) F&B — breakfast quality benchmarks, in-room dining menu depth; (5) Sustainability — minimum green practices required; (6) Safety and security — CCTV coverage, fire system certification; (7) Staff — language requirement, uniform standard, grooming policy; (8) Data and loyalty — CRM minimum requirements, brand app integration. Score each dimension out of 10, identify the highest-priority gaps, estimate the cost to close them, and recommend whether joining the soft brand is commercially justified.","tags":["hotels","branding","operations"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

    {"id":"hsp-45","title":"Restaurant Social Media Content Strategy","prompt":"Design a 90-day social media content strategy for a 70-cover farm-to-table restaurant with 2,800 Instagram followers and a goal of reaching 8,000 by the end of the quarter. The restaurant has no dedicated marketing resource — the content must be creatable by the chef and front-of-house manager in under 4 hours per week. Build: the content pillars (4 themes that will anchor all posts — define each pillar, the tone, the posting frequency, and the format), a 12-week content calendar with specific post ideas for each week (not vague categories but actual post concepts, e.g. 'Tuesday Reel: Chef visiting the farm at 6AM, picking this week's beetroot, scored to ambient field sounds'), the Instagram bio and link-in-bio strategy, the 5 highest-performing caption frameworks for restaurant content with examples, the hashtag strategy (mix of location, food community, and niche tags), the engagement ritual (how to spend 15 minutes per day building community without buying followers), and the metric review at 30, 60, and 90 days.","tags":["marketing","restaurant","social-media"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

    {"id":"hsp-46","title":"Hotel Accessibility Compliance Review","prompt":"Conduct a comprehensive accessibility compliance review framework for a 4-star hotel built in 1987 that has never undergone a formal accessibility audit. The review must address both legal compliance and genuine hospitality for guests with disabilities. Cover: the physical environment audit checklist (entrance, reception desk height, lift dimensions, accessible room specifications, bathroom grab rail placement, pool lift, restaurant table clearance), the communication and booking accessibility requirements (website screen reader compatibility, accessible room photography, booking phone line for guests who cannot use online booking), the staff training module on disability etiquette (language guidance, how to offer assistance without being patronizing, the specific protocols for guests who are deaf, blind, use a wheelchair, or have cognitive differences), the accessible room amenity standard, and the improvement priority matrix ranking required changes by impact and cost. Estimate the budget range for a full remediation program.","tags":["accessibility","compliance","hotels"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

    {"id":"hsp-47","title":"Hotel Revenue Strategy During Economic Downturn","prompt":"You are a revenue management consultant. A 155-room upscale hotel is entering a period of anticipated demand compression — the local corporate market is softening, advance bookings are running 18% behind the same period last year, and two new supply additions (a 180-room Marriott and a 120-room Hilton) have just opened in the same submarket. The ownership is demanding you protect ADR; the GM wants to fill rooms. Develop a recession-resilient revenue strategy that navigates this conflict. Address: the strategic rate positioning decision (when to hold rate versus when to tactically stimulate demand with value-adds versus when to discount — and the specific thresholds that trigger each response), the segment mix shift strategy (leisure versus corporate versus groups — which segments grow in a downturn and how to access them), the length-of-stay optimization to protect ADR while improving occupancy, the OTA strategy for last-minute distressed inventory, and the cash flow protection measures. Include a scenario analysis for three demand outlooks: base, pessimistic, and optimistic.","tags":["revenue-management","strategy","hotels"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

    {"id":"hsp-48","title":"Food and Beverage Franchise Feasibility","prompt":"[Describe your property — type, size, location, current F&B setup (if any), your available floor space for a food concept, and your budget range for the fit-out.]\n\nConduct a feasibility analysis for introducing a franchise food and beverage brand into the property described. Cover: the case for franchise versus independent concept (the trade-offs of brand recognition, franchise fees, menu inflexibility, and operational simplicity), the franchise screening framework (evaluate 3 relevant franchise options against criteria including franchise fee, royalty %, minimum turnover guarantee, training support, and brand fit with the hotel guest profile), the financial model (build the P&L for Year 1 and Year 2 including franchise fees, projected covers, APC, food cost, labor, and occupancy cost — state your assumptions clearly), the landlord negotiation strategy for the franchise agreement, and the integration plan covering how the franchise operation will interact with hotel services (room service delivery, billing to room, staff uniforms). Give a clear Go / No-Go recommendation with rationale.","tags":["f&b","franchise","finance"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

    {"id":"hsp-49","title":"Hospitality Leadership Development Program","prompt":"Design a 12-month leadership development program for 8 high-potential supervisors identified as future department heads in a luxury hotel group. The program must develop both technical hospitality competencies and leadership capability. Structure it as: 4 residential workshops (one per quarter — each 2.5 days, define the content and the learning method for each), a cross-departmental rotation schedule (each participant spends 3 months in 3 departments outside their home function), a mentoring program pairing each participant with a senior leader (define the meeting cadence, the conversation structure, and the sponsor's commitment), a live business challenge component where each participant leads a real revenue or guest satisfaction improvement project, and an individual development plan template. Define the competency framework the program develops against, the assessment at entry, mid-point, and graduation, and the clear pathway from graduation into a department head role within 18 months.","tags":["hr","leadership","hotels"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

    {"id":"hsp-50","title":"Restaurant Turnaround Strategy","prompt":"[Describe your restaurant — concept, location, number of covers, how long it has been open, current weekly covers, revenue, and the primary reasons you believe it is underperforming.]\n\nDevelop a 90-day turnaround strategy for the restaurant described. Diagnose the most likely failure drivers across four areas: (1) Concept and market fit — is the food style, price point, and ambience aligned with who actually walks past the door versus who you designed for? (2) Operations — identify the 3 most likely service or kitchen failures depressing repeat visits and review scores. (3) Financial structure — review whether the rent-to-revenue ratio, food cost, and labor model are structurally viable or whether the business model is broken regardless of operational improvement. (4) Marketing and awareness — assess whether the restaurant has a discoverability problem or a conversion problem. For each diagnosis area, provide the specific corrective action, the owner's time commitment required, the cost, and the expected impact on weekly covers within 90 days.","tags":["restaurant","turnaround","strategy"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":true},

    {"id":"hsp-51","title":"Hotel Direct Booking Engine Optimization","prompt":"Conduct a conversion rate optimization audit for a hotel's direct booking engine. The hotel's website receives 18,000 unique visitors per month, of whom 2.1% complete a booking (industry benchmark for independent hotels: 3.5-4.5%). The conversion gap represents approximately €42,000 in lost monthly revenue at an average booking value of €220. Identify the 10 most common booking engine conversion killers and provide the specific fix for each. Cover: the homepage-to-booking-initiation drop-off (what navigation friction stops guests from clicking 'Book Now'), the rate comparison anxiety on the date selection page, the room selection page (how to use photography, descriptions, and social proof to increase upsells to superior rooms), the extras and packages page (the one change that most reliably increases add-on attachment rate), the payment page (trust signals and form field optimization), and the abandonment recovery email sequence. Estimate the revenue impact of improving conversion from 2.1% to 3.0%.","tags":["hotels","digital","revenue-management"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

    {"id":"hsp-52","title":"Kitchen Brigade Restructure Plan","prompt":"Act as a culinary operations consultant. A hotel kitchen supporting a 130-cover restaurant, a 40-room in-suite dining operation, and banqueting for up to 300 covers currently employs 18 kitchen staff at a total annual labor cost of €680,000 (41% of F&B revenue, against a benchmark of 32-35%). The Head Chef has a team of 4 sous chefs, 6 chefs de partie, 4 commis, 3 kitchen porters, and 1 pastry chef. Analyze the structure and design a restructured brigade. Address: the span of control at each level, the multiskilling opportunity (which stations can be cross-trained to reduce headcount during shoulder-period services), the scheduling model to reduce overtime (the specific shift pattern design for a 7-day operation with 2.5 shifts per day), the banqueting surge model (how to scale up for a 300-cover event without employing full-time banqueting-only staff), and the labor cost projection after restructuring. Maintain the quality standard and identify any roles where the saving is not worth the service risk.","tags":["f&b","hr","operations"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

    {"id":"hsp-53","title":"Hotel Upselling Training Program","prompt":"Design a comprehensive upselling training program for hotel front desk agents. The hotel currently achieves a room upgrade upsell rate of 9% at an average upgrade revenue of €28 per upgraded stay. The target is 22% at €35. Build the complete training program: the mindset module (reframe upselling from 'pushing' to 'offering a better experience' — include the psychological research on why most front desk agents fail to upsell and how to overcome it), the product knowledge module (teach agents to anchor every upsell to the specific benefit for the guest standing in front of them, not a generic list of room features), the conversation framework (the 4-step upsell conversation: read the guest, bridge to the upgrade, paint the picture, handle the hesitation), role-play scripts for 6 guest profiles (business traveler, anniversary couple, family with young children, solo leisure, group of friends, disgruntled guest), and the post-training performance coaching template for supervisors. Project the annual revenue impact of reaching the 22% target.","tags":["sales","training","hotels"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

    {"id":"hsp-54","title":"Hotel Sustainability Report for Investors","prompt":"Write a comprehensive sustainability report for a 190-room luxury hotel to be presented to the ownership group and potential ESG-focused investors. The report should cover the property's performance across the three pillars of environmental, social, and governance. Environmental section: current carbon footprint (Scope 1, 2, and 3 estimates), energy and water intensity metrics per occupied room night with year-on-year trend, waste diversion rate, single-use plastic elimination progress, and the 3-year net zero pathway with capital investment required. Social section: staff diversity data by department and level, living wage compliance, local supplier spend percentage, community partnerships, and gender pay gap analysis. Governance section: anti-bribery policy, data protection compliance, food safety audit results, and board-level sustainability oversight. Conclude with a materiality assessment and the 5 sustainability initiatives with the highest combined ESG impact and commercial return for the next 3 years.","tags":["sustainability","finance","hotels"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

    {"id":"hsp-55","title":"Catering and Banqueting Profitability Review","prompt":"You are a food and beverage consultant. A hotel's banqueting and catering department generated €1.6M in revenue last year from 180 events but achieved only a 14% departmental profit margin against a budget of 22%. Conduct a full profitability review. Analyze: the event type mix (weddings, corporate dinners, private parties, conference lunches) and the margin by event type — identify which event types are loss-makers and why, the menu pricing audit (compare your per-head pricing to 3 competitor venues and assess whether you are over-delivering on quality relative to price), the labor model (banqueting labor is typically the largest cost variance — analyze the variable staffing model, overtime triggers, and agency staff cost), the beverage revenue per head (the most underperforming revenue line in most banqueting operations), and the sales process (are you converting enquiries efficiently and are you selling the right packages). Produce a 12-month improvement plan that recovers margin from 14% to 21%.","tags":["f&b","events","finance"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

    {"id":"hsp-56","title":"Hotel Guest Review Management Strategy","prompt":"Design a complete online review management strategy for a hotel currently sitting at an 8.1 on Booking.com, a 4.2 on TripAdvisor, and a 4.4 on Google. The comp set average across all three platforms is 8.6, 4.5, and 4.6 respectively. The most frequent negative themes in current reviews are: slow check-in (mentioned in 34% of negative reviews), breakfast quality declining since the chef change 4 months ago (28%), and Wi-Fi reliability (19%). Build: the root cause diagnosis and corrective action plan for each of the three recurring complaint themes, the review response template library (write 5 different response frameworks for the most common positive and negative scenarios), the internal review monitoring process (who reads reviews, in what frequency, how insights are fed back to operations), the staff recognition program linked to positive guest mentions, and the in-stay intervention strategy to identify dissatisfied guests before they check out and write a negative review. Project the commercial impact of moving from 8.1 to 8.5 on Booking.com in terms of ranking visibility and conversion.","tags":["guest-experience","marketing","hotels"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

    {"id":"hsp-57","title":"Pop-Up Dining Experience Design","prompt":"Act as a creative F&B consultant. Design a series of three pop-up dining experiences for a luxury hotel to run quarterly during traditionally slow periods. Each pop-up should be a distinct, ticketed, social-media-worthy event that attracts both hotel guests and the local food community. For each event design: the concept and narrative (the story that makes someone buy a ticket), the venue setup within or around the hotel (be specific — rooftop at sunset, the wine cellar, the kitchen counter), the menu (5 courses, each with a name and a 2-sentence description that captures the theatre), the theatrical service element that makes at least one moment 'shareable,' the ticket pricing and the commercial model, the marketing launch strategy (Instagram countdown, email to the restaurant database, PR outreach to one food journalist), and the production timeline from concept to execution. Also outline how the pop-up series contributes to the hotel's positioning as a food destination rather than a hotel with a restaurant.","tags":["f&b","events","marketing"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

    {"id":"hsp-58","title":"Hotel Franchise vs. Independent Decision Analysis","prompt":"[Describe your hotel — number of rooms, location, current brand affiliation (if any), current performance metrics (occupancy, ADR, RevPAR), and the franchise or soft brand options you are evaluating.]\n\nConduct a rigorous franchise versus independent decision analysis for the hotel described. Cover: the revenue impact analysis (what incrementally higher occupancy and ADR does the brand's distribution system and loyalty program realistically deliver, based on comparable hotels that have converted in similar markets), the cost analysis (franchise fee structure, royalty percentage, program fees, PIP capital requirements, and the total annual cost of brand affiliation as a percentage of revenue), the management flexibility trade-off (what operational decisions does the franchise agreement constrain, and how much does this matter for your specific property), the exit analysis (what are the penalties for leaving the franchise in years 1, 3, and 5), and the 5-year NPV comparison between joining the brand versus remaining or becoming independent with a soft brand. Give a clear recommendation with the 3 critical assumptions your recommendation depends on.","tags":["hotels","strategy","finance"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

    {"id":"hsp-59","title":"Hotel Night Audit and Financial Controls","prompt":"Design a comprehensive night audit process and financial controls framework for a 130-room hotel. The night audit is currently a manual process taking 3.5 hours and frequently producing reconciliation errors. Cover: the modernized night audit workflow using the property's PMS (step-by-step process for room revenue posting, no-show charge processing, advance deposit reconciliation, and credit card batch settlement), the daily financial control reports that should be generated and reviewed by the GM each morning (the 5 reports with the specific line items to check and the action to take if a variance is found), the cash handling controls for the front desk (the opening float procedure, the till reconciliation process, the safe deposit protocol), the internal audit checklist for detecting the 6 most common forms of front desk fraud in hotels, and the month-end close process linking the night audit to the management accounts. Estimate the time saving from automating the current manual process and the error rate reduction.","tags":["finance","operations","hotels"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

    {"id":"hsp-60","title":"Hospitality Technology Innovation Roadmap","prompt":"You are a chief technology officer for a mid-scale hotel group with 12 properties. Develop a 3-year technology innovation roadmap that delivers measurable improvements in guest experience and operational efficiency. The roadmap must be financially justified and operationally realistic — not a wish list. Structure it by horizon: Horizon 1 (Year 1) — Foundational digital infrastructure: mobile check-in and digital key deployment across all properties, PMS integration with all OTAs via a central channel manager, and a unified guest data platform to enable personalization at scale. Horizon 2 (Year 2) — Intelligence layer: AI-powered revenue management replacing manual rate setting, automated guest messaging at every touchpoint using natural language AI, and predictive maintenance using IoT sensor data. Horizon 3 (Year 3) — Differentiation: robotics for back-of-house tasks (linen delivery, housekeeping carts), voice-controlled in-room experience, and a first-party data marketing platform replacing OTA dependence. For each initiative include build-versus-buy decision, estimated cost, projected ROI, and the organizational capability needed to succeed.","tags":["technology","hotels","innovation"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":true},

    {"id":"hsp-61","title":"Inclusive Hospitality Design Standards","prompt":"Develop inclusive design standards for a new 120-room hotel being designed from scratch. The brief is to create a property where guests of all abilities, backgrounds, and identities feel genuinely welcomed, not merely legally accommodated. Cover: physical design (beyond ADA minimums — sensory-friendly room options, gender-neutral bathrooms, prayer and meditation spaces, quiet zones in public areas), service design (staff communication training for guests with disabilities, LGBTQ+ affirmation practices, cultural and religious dietary accommodation standards), booking and digital access (screen reader compatibility, alternative contact methods, pre-arrival needs assessment form), staff representation and inclusion (hiring practices, language support for multilingual guests, cultural celebration in the F&B program), and the guest-facing communication of these commitments. Identify the 5 design choices that will most visibly signal to guests from underrepresented groups that they are genuinely welcome — not as an afterthought but as the intended guest.","tags":["inclusion","design","hotels"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

    {"id":"hsp-62","title":"Restaurant Franchise Development Manual","prompt":"Write a franchise development operations manual for a fast-casual restaurant concept preparing to sell its first 5 franchise units. The concept is a 60-cover Mediterranean bowl restaurant with a proven 3-unit company-owned track record generating an average unit volume of €820,000 per year and a 19% EBITDA margin. The manual must give a prospective franchisee everything they need to understand the investment and operations. Cover: the franchise disclosure document summary (investment range, franchise fee, royalty structure, territory definition), the site selection criteria and the scoring matrix the franchisor uses to approve new locations, the fit-out specification (kitchen layout, equipment list, interior design standards with specification guide), the initial training program (4-week curriculum at the training restaurant plus 2 weeks on-site opening support), the ongoing support model (field visits, digital training platform, marketing fund management), and the key performance indicators a franchisee is monitored against quarterly. Include the franchisee profile and the financial qualification requirements.","tags":["restaurant","franchise","strategy"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

    {"id":"hsp-63","title":"Hotel Corporate Social Responsibility Program","prompt":"Design a comprehensive CSR program for a 220-room city-center hotel that currently has no formal community engagement or philanthropic strategy. The program must be authentic, operationally feasible, and genuinely impactful rather than a marketing exercise. Build the program across three pillars: Community (a skills-based employment program partnering with a local youth unemployment charity — design the training pathway from first interview to a paid housekeeping or kitchen position within 8 weeks), Environment (a water stewardship initiative in partnership with the local watershed authority — define the 2-year water reduction targets and the guest communication), and Culture (a 'local artist in residence' program giving 4 artists per year a studio space in the hotel in exchange for artwork displayed in guest corridors — define the selection process and the commercial arrangement). For each pillar define: the operational commitment, the staff volunteer hours required, the budget, the measurement framework, and the storytelling strategy that builds genuine stakeholder trust.","tags":["csr","hotels","community"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

    {"id":"hsp-64","title":"Michelin Star Restaurant Service Standards","prompt":"You are the maître d' of a restaurant aspiring to earn its first Michelin star within 18 months. Develop the complete front-of-house service standards manual that meets Michelin inspectors' expectations. Cover: the pre-service mise en place checklist (tabletop geometry, glassware polishing standard, flower arrangement guideline, ambient temperature and lighting check), the welcome and seating ritual (the choreography from door to seated, including the coat check, menu presentation sequence, and opening dialogue that avoids the cliché 'Is this your first time with us?'), the menu navigation guidance for servers (how to describe dishes without reciting ingredients, how to read a guest's food knowledge level and pitch the conversation accordingly), the wine service standards (decanting decision criteria, temperature checking protocol, the sommelier's tableside conversation arc), the pacing management (how to control the tempo of the meal without making guests feel rushed or forgotten), and the inspector scenario — describe how the team should behave if an inspector is suspected at table 8.","tags":["fine-dining","restaurant","luxury"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":true},

    {"id":"hsp-65","title":"Hotel Distribution Strategy Review","prompt":"Conduct a comprehensive distribution strategy review for a 170-room resort hotel. Current channel mix: OTAs (Booking.com 38%, Expedia 14%), direct website 18%, direct phone and email 12%, GDS 8%, tour operators 10%. Total OTA commission cost is €480,000 per year. Total distribution cost as a percentage of rooms revenue is 24% against a benchmark of 18%. The GM wants to reduce distribution cost to 19% within 2 years without losing volume. Analyze each channel: the net RevPAR contribution of each channel after all commissions and costs, the strategic role of each channel (volume, premium segment access, geographic reach, last-minute fill), and the realistic opportunity to grow lower-cost channels. Build the 2-year distribution rebalancing plan: the specific actions to grow direct from 18% to 30% (website investment, email marketing, metasearch), the GDS strategy for corporate accounts, the tour operator contract renegotiation approach, and the OTA strategy as a yield tool for last-minute and distressed inventory rather than a primary channel.","tags":["distribution","revenue-management","hotels"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

    {"id":"hsp-66","title":"Hospitality Startup Pitch Deck","prompt":"[Describe your hospitality startup concept — the problem it solves, the product or service, the target customer, how far along you are in development, and how much investment you are seeking.]\n\nWrite a complete 12-slide pitch deck outline for the hospitality startup described, designed to secure seed investment from a hospitality-focused venture fund. For each slide provide: the title, the 3-5 bullet points of content, the one visual or data point that anchors the slide, and the key message the investor should leave with. Slide sequence: (1) Problem — the acute pain in the hospitality market you are solving, (2) Solution — your product in one sentence and one demo visual, (3) Why Now — the market timing factors that make this the right moment, (4) Market Size — TAM/SAM/SOM with hospitality-specific segmentation, (5) Product — how it works with a UX walkthrough, (6) Business Model — revenue streams and unit economics, (7) Traction — evidence to date (pilots, revenue, LOIs, partnerships), (8) Competition — the honest landscape and your defensible moat, (9) Go-to-Market — the first 12 months of customer acquisition, (10) Team — why you specifically can win this, (11) Financials — 3-year model with key assumptions, (12) The Ask — amount, use of funds, milestones unlocked.","tags":["startup","hospitality","investment"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

    {"id":"hsp-67","title":"Hotel Procurement Strategy","prompt":"Design a strategic procurement program for a 240-room full-service hotel currently spending €4.2M per year across food and beverage (€1.8M), FF&E and OS&E (€640K), energy (€480K), laundry and linen (€220K), and miscellaneous services (€1.06M). The hotel has no formal procurement function — each department head orders independently with no volume aggregation. Estimate the total saving opportunity from professionalizing procurement and build the implementation plan. Cover: the spend analysis and vendor rationalization (identify the categories with the highest concentration of savings — typically food, beverages, and energy), the supplier tender process for the top 5 spend categories (timeline, specification document, evaluation criteria, negotiation approach), the contract management framework (SLA definition, price escalation clauses, volume commitment structure, exit rights), the sustainable procurement policy (minimum ethical sourcing standards for food, and environmental certifications for cleaning products and consumables), and the organizational model (should this be a dedicated role or a GM-led committee?). Project Year 1 and Year 2 savings.","tags":["procurement","operations","hotels"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

    {"id":"hsp-68","title":"Hotel Market Feasibility Study Framework","prompt":"Design the methodology for a hotel market feasibility study for a proposed 110-room boutique lifestyle hotel in a secondary city with a population of 380,000. The investor has a site secured and a construction budget of €18M. Walk through the complete feasibility methodology: (1) Market overview — GDP growth, inbound tourism trends, airlift data, demand generators (corporate, leisure, events) and their stability, (2) Supply analysis — the competitive set (define it, exclude branded giants, focus on the true comp set of 4-6 properties), their current performance, and any new supply in the pipeline, (3) Demand analysis — the segmentation of the market by origin and purpose, the primary demand generators and their distance from the site, (4) Performance projection — the stabilized year occupancy (typically Year 3), ADR, and RevPAR projection with the assumptions behind each, (5) Financial feasibility — the hotel P&L from RevPAR to GOP to NOI, the capitalization rate applied, the implied asset value, and the return on investment at the proposed construction cost. State where the study would recommend proceeding and what the critical risk factors are.","tags":["hotels","investment","strategy"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

    {"id":"hsp-69","title":"Restaurant Menu Redesign for Profitability","prompt":"Act as a menu consultant. A 90-cover Mediterranean restaurant has a current menu of 52 items across 8 sections. The GM reports that servers say the menu is 'too long and guests take too long to decide.' The average check is €36 against the owner's target of €44. Food cost is 34% against a target of 30%. Design the complete menu redesign. Cover: the optimal number of items per section and the research behind the decision (the paradox of choice in restaurant settings), the menu layout redesign to guide the eye toward high-margin items (the 'golden triangle' of menu real estate and how to use it), the item rationalization process (which of the 52 items to cut and the criteria for that decision), the price architecture redesign (how to increase perceived value without a straight price increase — anchor pricing, decoy items, price rounding), the description rewrite for the 10 hero items (rewrite each with sensory language that increases order frequency), and the projection for average check and food cost percentage after the redesign.","tags":["restaurant","menu","profitability"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

    {"id":"hsp-70","title":"Hotel Pandemic and Epidemic Response Plan","prompt":"Develop a comprehensive health crisis response plan for a 200-room full-service hotel to manage a public health emergency, drawing lessons from the operational challenges revealed during the COVID-19 pandemic. The plan should be updated annually and cover four phases: Phase 1 — Preparedness (the baseline public health protocol: staff health monitoring, enhanced cleaning standards for high-touch surfaces, ventilation audit, PPE stockpile, supplier continuity risk assessment); Phase 2 — Escalation response (protocols triggered when a guest or staff member tests positive for a communicable disease on property — room isolation procedure, contact tracing cooperation, deep cleaning protocol, guest communication script, owner and insurance notification); Phase 3 — Restricted operations (the scaled-down operating model for low occupancy — which outlets to close, minimum staffing by department, cash flow preservation measures, government support scheme monitoring); Phase 4 — Recovery (the demand generation strategy for the post-crisis recovery period, the staff recall sequence, and the physical and procedural changes that become permanent). Name the staff member responsible for each phase.","tags":["crisis-management","hotels","operations"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

    {"id":"hsp-71","title":"Luxury Hospitality Brand Identity Development","prompt":"[Describe your luxury hotel or hospitality brand — the physical property, the location, the target guest, the inspiration behind the concept, and any existing brand elements (name, logo, color palette) already in place.]\n\nDevelop the complete brand identity for the luxury hospitality brand described. Cover: the brand purpose statement (the deeper 'why' beyond providing accommodation — the transformation the brand creates in the guest), the brand personality (6 adjectives and the behaviors they produce in service delivery, not just marketing copy), the visual identity direction (primary color palette with the emotional rationale for each color, typography pairing, photography style with 3 reference images described in detail, iconography and pattern language), the brand voice guide (the writing principles with 5 before-and-after examples showing how generic hospitality language becomes distinctively on-brand), the naming system for branded experiences (how the spa, the restaurant, the suites, and the amenity products are named within the brand architecture), and the brand touchpoint priority map (the 5 guest touchpoints where the brand identity must be most perfectly expressed and why).","tags":["branding","luxury","hotels"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

    {"id":"hsp-72","title":"Hotel Staff Scheduling Optimization","prompt":"You are a hotel operations consultant specializing in labor optimization. A 160-room hotel has a total annual labor cost of €3.8M representing 42% of total revenue (industry target: 33-36%). The largest overrun is in Rooms Division: housekeeping and front desk together are €180,000 over budget for the year. The scheduling is done weekly by department heads using spreadsheets with no connection to occupancy forecast data. Design the complete labor optimization program: the demand-driven scheduling model (how to link the weekly room occupancy forecast to the staffing requirement for each department, with the formula for calculating required housekeeping hours based on occupied rooms, stay-overs, and departure rooms), the staggered shift design to match check-in and check-out peaks, the casual and zero-hours worker pool management for demand surge, the scheduling software selection criteria, and the supervisor accountability framework (the weekly labor cost review that each department head presents to the GM). Project the saving from moving to demand-driven scheduling.","tags":["hr","operations","hotels"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

    {"id":"hsp-73","title":"Agritourism Development Plan","prompt":"[Describe your agricultural property — location, size, what you currently produce, existing infrastructure (accommodation, barn space, visitor facilities), and your current income from farming versus any tourism activity.]\n\nDevelop a comprehensive agritourism business plan for the property described. Cover: the market positioning (define the specific agritourism experience you are uniquely placed to offer — harvest stays, farm-to-table dinners, agricultural education, craft production workshops), the guest experience design (the weekly guest programme from arrival to departure, including 3 signature activities that no nearby competitor can replicate), the accommodation development plan (recommend the accommodation type and number of units that balances investment cost against revenue potential — glamping, converted barn rooms, self-catering cottages), the revenue model (the income streams, pricing, seasonality analysis, and Year 1 to Year 3 revenue projection), the planning and licensing requirements for food service and accommodation in your jurisdiction, the marketing strategy to reach the agritourism target guest, and the agricultural integrity question — how do you grow tourism without compromising the working farm that is the product's soul.","tags":["agritourism","tourism","strategy"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

    {"id":"hsp-74","title":"Hotel Revenue Management System Selection","prompt":"Guide a 190-room independent hotel through the process of selecting and implementing its first automated Revenue Management System. The hotel currently sets rates manually — the GM updates OTA rates twice per week based on a spreadsheet and gut feel. ADR is running 12% below the comp set. Build the complete RMS selection and implementation guide: the business case for automation (calculate the expected ADR improvement and RevPAR impact at 5%, 8%, and 12% upside scenarios), the RMS requirements specification (the 12 functional requirements to include in the vendor RFP, weighted by importance for an independent hotel), the vendor evaluation framework (evaluate 4 leading RMS platforms against the specification — cover price, PMS integration depth, forecast methodology, user interface for a non-technical GM, and customer support), the implementation timeline (data migration, historical data loading, parallel running period, go-live), and the performance review framework at 90 days, 6 months, and 12 months to confirm the system is delivering the promised uplift.","tags":["revenue-management","technology","hotels"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

    {"id":"hsp-75","title":"Food and Beverage Concept Refresh","prompt":"[Describe your current F&B outlet — the concept, the physical space, the number of covers, the current positioning and price point, how long it has operated under the current concept, and the primary reason you believe a refresh is needed.]\n\nDesign a complete concept refresh for the F&B outlet described. A concept refresh is not a full rebrand — it evolves the existing concept to remain relevant without abandoning the equity already built. Cover: the concept audit (what is working and must be retained, what is dated and must evolve), the new positioning statement that sharpens the identity without alienating regulars, the menu refresh framework (how many dishes to retain, how many to replace, the new hero dishes, and the menu design evolution), the physical environment refresh (the changes that create a new energy without a full refit — lighting, music, tabletop, staff uniform detail), the name and identity evolution (should it remain the same name or take a refreshed identity?), the staff re-engagement program (how to bring the team on the journey so they are ambassadors not skeptics), and the relaunch communications strategy including a soft launch event for regulars before the public announcement.","tags":["f&b","restaurant","strategy"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

    {"id":"hsp-76","title":"Hospitality Revenue Management Certification Study Guide","prompt":"Create a comprehensive study guide for a hospitality professional preparing for a Revenue Management certification examination. The guide should cover all core competencies tested in industry-standard exams. Structure it as follows: Module 1 — Fundamentals (the definition and principles of revenue management, the history from airlines to hotels, the conditions required for RM to work — perishable inventory, variable demand, advance booking), Module 2 — Metrics mastery (define and provide worked calculation examples for: Occupancy %, ADR, RevPAR, TRevPAR, GOPPAR, NRevPAR, RGI, ARI, MPI, RevPASH for restaurants), Module 3 — Forecasting (the additive and multiplicative seasonal decomposition methods, the pickup model, and how to evaluate forecast accuracy using MAPE), Module 4 — Distribution (OTA algorithm factors, metasearch, the cost of each distribution channel, parity management), Module 5 — Pricing strategy (BAR ladders, length-of-stay controls, overbooking models, group displacement), and Module 6 — Practice exam (20 multiple-choice questions with full worked answers).","tags":["revenue-management","education","hotels"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

    {"id":"hsp-77","title":"Hotel Concierge Excellence Program","prompt":"Design an excellence program for a hotel concierge team of 6 covering a luxury 5-star property in a major European city. The concierge team currently has a guest satisfaction score of 4.3/5 with the primary complaints being generic recommendations and slow response times for difficult requests. Build the program: the local knowledge curriculum (the 20 categories of city knowledge every concierge must master — from the best shoe repair to where to find a rare book — and the ongoing learning cadence to keep knowledge current), the network-building program (how each concierge builds genuine relationships with 80 local contacts including restaurant managers, gallery directors, transport operators, and fixers, and the protocol for maintaining those relationships), the difficult request protocol (the decision tree for saying 'not possible' versus escalating to a fixer contact, and the 3 cases where the concierge should offer a memorable alternative rather than fulfilling the request literally), the response time standards by request type, and the knowledge-sharing system so the team's combined expertise is accessible to all members during any shift.","tags":["guest-experience","luxury","hotels"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

    {"id":"hsp-78","title":"Hotel Investment Memorandum","prompt":"Write a hotel investment memorandum for a 88-room boutique hotel in a growing secondary city being offered to private equity investors at an asking price of €12.5M. The hotel generated €2.8M in revenue and €560K in EBITDA in the trailing 12 months (20% EBITDA margin). The market has seen 6% RevPAR growth per year for 3 consecutive years. The investment thesis is a value-add play: the new owner repositions the property from 3-star to 4-star through a €1.8M refurbishment, drives ADR from €98 to €135 within 36 months, and targets a 28% EBITDA margin on a stabilized revenue of €3.9M. Structure the memorandum: Executive Summary, Investment Highlights, Property Description, Market Analysis, Historical Financial Performance, The Business Plan (refurbishment, repositioning, revenue growth strategy), Financial Projections (3-year P&L and cash flow), Exit Strategy (target buyer profile, exit cap rate assumption, projected exit value), and Risk Factors with mitigants. The tone should be factual, sophisticated, and appropriate for a professional investor audience.","tags":["investment","hotels","finance"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":true},

    {"id":"hsp-79","title":"Culinary Tourism Experience Design","prompt":"Design a portfolio of culinary tourism experiences for a mid-size European city with a strong regional food culture, a developing wine region 45 minutes away, and a traditional market that has operated for 200 years. The city's tourism board wants to position food as the primary reason to visit, not a secondary benefit. Create 5 distinct culinary tourism products: (1) A morning market tour and cooking class (full design — what the guide says, what guests cook, the social media moment, the pricing), (2) A winemaker dinner in the vineyard (the evening programme, the chef collaboration, the storytelling arc, the pricing and logistics), (3) A street food trail map (8 stops, the story of each vendor, the app or printed guide design), (4) A 3-day culinary immersion package (the complete itinerary, accommodation recommendation, the 'hands-dirty' experience at a local producer that no tour operator currently offers), (5) A private chef's table in a restaurant kitchen (the pitch to 5 restaurants, the revenue share model, the guest profile who buys this). Include the packaging and marketing strategy for selling all five as a city-wide food tourism brand.","tags":["tourism","f&b","experience-design"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

    {"id":"hsp-80","title":"Hotel General Manager Performance Scorecard","prompt":"Design a comprehensive performance scorecard for a Hotel General Manager that the ownership group or asset manager uses for quarterly performance reviews and annual compensation decisions. The scorecard must balance financial performance, guest experience, team engagement, and asset stewardship. Define every KPI: (1) Financial — RevPAR index versus budget and comp set, GOPPAR versus budget, labor cost %, distribution cost %, CapEx spend within approved budget; (2) Guest Experience — NPS or overall satisfaction score versus target and prior year, response rate to reviews, complaint volume and resolution rate; (3) People — staff turnover by department versus industry benchmark, eNPS (employee Net Promoter Score), training hours per employee, succession plan completeness; (4) Asset — preventative maintenance compliance rate, energy intensity versus benchmark, health and safety audit score; (5) Strategic — progress against 3 strategic objectives set at the start of the year. For each KPI provide the weighting in the overall scorecard, the measurement frequency, and the consequence at each performance level (Below Threshold, Meets Target, Exceeds Target).","tags":["management","hotels","hr"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

    {"id":"hsp-81","title":"Zero-Waste Restaurant Kitchen Design","prompt":"Act as a culinary sustainability consultant. Design the operational philosophy and physical layout of a zero-waste restaurant kitchen for a new 80-cover restaurant. Zero-waste means less than 5% of incoming food materials leave as non-edible waste. Cover: the procurement discipline required before a single ingredient enters the kitchen (the 5 pre-purchase questions: can we use the whole animal or vegetable, is the yield acceptable, can the trim become another dish), the menu architecture that builds whole-ingredient thinking into every dish (provide a worked example of a whole celeriac menu — root, stalk, leaves, peel — showing how one ingredient becomes 4 components across the menu), the kitchen flow design to physically separate prep waste by stream (usable trim, compostable organic, packaging), the daily waste log template and the brigade's accountability ritual, the partner ecosystem (the local pig farmer who takes spent grain, the biodigester service for unavoidable organic waste, the packaging return program with suppliers), and the guest communication that makes the zero-waste commitment a compelling dining narrative without being preachy.","tags":["sustainability","restaurant","operations"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

    {"id":"hsp-82","title":"Hotel Staff Wellbeing Program","prompt":"Design a comprehensive staff wellbeing program for a 280-person hotel workforce. Hospitality has one of the highest burnout and turnover rates of any industry — this program must address the structural causes, not just provide a yoga class. Cover: the physical wellbeing tier (ergonomic assessments for housekeeping and kitchen staff, healthy staff meals program, rest area redesign — the current staff room is a converted storage room with vending machines), the mental health tier (an Employee Assistance Program with 6 free counselling sessions, a mental health first aider in every department, a manager training module on recognizing burnout before it becomes resignation), the financial wellbeing tier (access to wages before payday via an earned wage access app, financial literacy workshop, tip transparency policy), the social wellbeing tier (a cross-departmental social committee with a quarterly events budget, a recognition culture reset starting with the GM's weekly shoutout habit), and the measurement framework (track eNPS every quarter, absenteeism rate, and voluntary turnover — set a target of reducing voluntary turnover by 20% in Year 1 and calculate the saving).","tags":["hr","wellbeing","hotels"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

    {"id":"hsp-83","title":"Hotel Management Agreement Negotiation Guide","prompt":"You are a hotel owner negotiating a new hotel management agreement with an international operator for a 175-room upscale hotel. This is your first management contract and the operator's standard terms are heavily weighted in their favor. Build a complete negotiation guide: the 10 most owner-unfavorable clauses in a standard HMA and the specific counter-proposal for each (cover: base management fee structure — push for full incentive alignment, performance test and termination rights, FF&E reserve contribution rate, operator-affiliated services restrictions, key money if applicable, exclusion of operator's above-property charges from GOP calculation, and change-of-ownership provisions), the performance test design (the specific RGI and GOPPAR thresholds the operator must meet, the cure period length, and the termination consequences), the owner's rights during the contract term (budget approval, key hire approval, asset inspection rights), the exit mechanics (the notice period, non-compete restrictions, and system extraction costs), and the 3 points where you should be willing to concede to protect the 5 points that are non-negotiable. Include a negotiation positioning note for each clause.","tags":["hotels","legal","strategy"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

    {"id":"hsp-84","title":"Tourist Accommodation Classification System","prompt":"[Describe the country or regional market you are operating in, the types of accommodation in your portfolio (hotels, guesthouses, apartments, glamping), and the current classification system in place if any.]\n\nDesign or evaluate a tourist accommodation classification system for the context described. Cover: the classification philosophy (star ratings versus descriptor-based grades versus experience-based certification — evaluate each approach and recommend the most appropriate for the market), the physical and service criteria at each classification level with minimum standards defined for: room size, bathroom specification, reception hours, food service, digital connectivity, accessibility provision, and sustainability practice, the inspection and enforcement methodology (self-assessment versus third-party audit versus mystery guest, frequency, and consequence of non-compliance), the guest communication of the classification on OTA platforms and in marketing materials, the graduated upgrade pathway so operators are incentivized to improve, and the equivalency mapping to international classification systems so foreign visitors can calibrate expectations. Identify the 3 most common flaws in existing national classification systems and how this design avoids them.","tags":["tourism","regulation","hotels"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

    {"id":"hsp-85","title":"Hotel Digital Transformation Strategy","prompt":"[Describe your property type, size, current technology infrastructure, the biggest operational pain points you want technology to solve, and your annual technology budget.]\n\nDevelop a digital transformation strategy for the property described. The strategy must be pragmatic — prioritizing the technology investments with the highest combined impact on guest experience, operational efficiency, and revenue — rather than a technology-for-technology's-sake exercise. Structure it in three layers: (1) Data foundation — the guest data infrastructure that enables personalization (unified guest profile, consent-based data collection, integration between PMS, CRM, and booking engine), (2) Automation layer — the repetitive operational tasks that AI and automation should handle (rate updates, review responses, pre-arrival messaging, upsell offer sequencing, demand forecasting), (3) Experience layer — the guest-facing digital touchpoints that add genuine convenience or delight (mobile check-in, digital key, in-room voice control, digital compendium, food and beverage ordering). For each investment provide: what pain point it solves, the specific vendor recommendation, the integration requirement, the cost, and the measurable outcome expected within 12 months.","tags":["technology","hotels","strategy"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

    {"id":"hsp-86","title":"Boutique Hotel Collection Brand Architecture","prompt":"You are a brand strategist working with a family that owns 5 independent boutique hotels across 3 countries (2 in Italy, 2 in Portugal, 1 in Morocco). Each property has a distinct character and its own name. The family wants to create a collection brand that adds distribution and loyalty power without homogenizing the properties. Design the brand architecture: the collection brand name and positioning (the unifying philosophy that all 5 hotels share — this must be a genuine commonality, not a marketing construct), the endorsed branding model (how to present both the collection brand and the individual hotel name so neither is diminished), the collection-level loyalty program that rewards guests who stay across multiple properties (the points structure, the cross-property benefit tiers, and the 'passport' reward for guests who stay at all 5 properties), the shared services that belong at the collection level (central reservations, revenue management, procurement, digital marketing) versus the decisions that stay with each property, the CRM strategy for cross-selling between properties, and the collection website architecture showing how each property is discoverable while also being celebrated individually.","tags":["branding","hotels","strategy"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":true},

    {"id":"hsp-87","title":"Hotel Food Safety Management System","prompt":"Design a comprehensive HACCP-based food safety management system for a hotel operating a full-service restaurant, a pool bar, a 24-hour room service kitchen, and banqueting for up to 400 covers. Cover: the hazard analysis for the 5 highest-risk food processes in a hotel kitchen (cook-chill for banqueting, high-risk garnishes such as raw sprouts and unpasteurized cheeses, allergen cross-contact, temperature control during buffet service, and raw seafood handling), the Critical Control Points with their critical limits and monitoring procedures, the corrective action protocols for each CCP failure (including the guest communication script when a corrective action affects a served dish), the verification schedule (the internal audit, the thermometer calibration log, the supplier audit program), the staff training and competency assessment for food handlers at every level from dishwasher to Head Chef, and the food safety culture program that makes compliance a team value rather than an inspection anxiety. Include the document control system and the record retention policy.","tags":["f&b","safety","compliance"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

    {"id":"hsp-88","title":"Eco-Lodge Development and Operations Plan","prompt":"[Describe the natural environment of your proposed eco-lodge — the location, the ecological features (forest, coastline, savanna, wetland), the nearest community, the land area available, and your development budget.]\n\nDevelop a complete eco-lodge development and operations plan for the project described. Cover: the development philosophy (define what 'eco' genuinely means for this project — the minimum standards for low-impact construction, water and energy independence, waste management, and biodiversity net gain), the accommodation design (the lodge type, number of units, and materials sourcing approach that minimizes ecological footprint), the guest experience programme (the daily itinerary of nature-based activities, the local guides employment model, and the one signature experience that cannot be found at any competing property within 200km), the community benefit model (what percentage of revenue goes to the local community, how hiring is structured to prioritize local employment, and the local enterprise supply chain), the marketing strategy to attract the high-value low-impact traveler (the specific publications, platforms, and booking channels that reach this guest), and the GSTC certification pathway with the 12 criteria that will require the most investment.","tags":["eco-tourism","hotels","sustainability"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

    {"id":"hsp-89","title":"Hotel Sales Team Structure and Incentive Design","prompt":"Design the complete sales team structure and incentive compensation plan for a 280-room full-service hotel with €9.2M in annual revenue. The current sales team of 3 has no clear account ownership, no formal KPIs, and no incentive scheme beyond a base salary. As a result, the corporate segment is declining, the MICE pipeline is thin, and the team is reactive rather than proactive. Build: the team structure (define 3 roles with clear segment ownership — corporate accounts, MICE and events, and leisure partnerships — including the account portfolio size for each), the prospecting and activity KPIs for each role (number of proactive calls per week, site visits per month, RFP responses within 24 hours, new account acquisition targets), the revenue targets by segment and the logic behind them, the incentive compensation design (base salary, commission on booked revenue, quarterly bonus on NPS for group events, and the SPIF structure for new business), the CRM discipline (the minimum data fields for every opportunity, the pipeline stage definitions, and the weekly pipeline review format), and the new business development strategy for the top 3 untapped corporate accounts in the local market.","tags":["sales","hotels","hr"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

    {"id":"hsp-90","title":"Restaurant Partnership and Collaboration Strategy","prompt":"Act as a restaurant business development consultant. Design a partnership strategy for a 65-cover independent restaurant that wants to grow revenue by 25% without increasing seating capacity. Identify and fully develop 5 partnership models: (1) A brewery collaboration — co-create a house beer range, design the cross-promotion plan and revenue share model; (2) A local producer showcase — design the monthly producer dinner format, the ticket pricing, the co-marketing split, and the PR strategy; (3) A corporate lunch account program — define the minimum spend qualification, the benefits, the billing model, and the target list of 10 local businesses to approach first; (4) A private dining partnership with a hotel — the commercial terms for the restaurant to provide private dining experiences for hotel guests who want something off-property, and the concierge relationship that drives the referral; (5) A cookery school — design the Saturday morning class format, the price per person, the equipment required, and the social media content it generates. For each partnership include the revenue projection, the operational commitment, and the risk.","tags":["restaurant","partnerships","strategy"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

    {"id":"hsp-91","title":"Hotel Revenue Management for Extended Stay","prompt":"Apply revenue management principles to an 80-unit extended stay property — a hybrid between a hotel and serviced apartments catering to guests staying between 7 and 90 nights. This property type has distinct demand patterns and pricing challenges compared to a transient hotel. Cover: the pricing architecture (how to build a length-of-stay discount ladder that rewards long stays without giving away margin on shorter stays — show the formula for the break-even LOS discount), the channel strategy (the extended stay booking channels are different from transient OTAs — corporate relocations, insurance companies, construction companies, digital nomads — define the sales approach for each), the lease versus hotel-rate hybrid model (when does it make sense to offer a quasi-lease agreement and what are the legal and operational implications), the revenue per unit metrics (adapt RevPAR to account for the monthly revenue pattern), and the ancillary revenue opportunities unique to extended stay (laundry packages, grocery delivery partnerships, co-working space for non-resident remote workers). Include a sample 30/60/90-night rate ladder with the rationale for each price break.","tags":["revenue-management","hotels","extended-stay"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

    {"id":"hsp-92","title":"Hospitality Conference Programme Design","prompt":"[Describe the conference — the target audience (who in hospitality is it for), the size (number of delegates), the duration, the venue type, and the primary themes or topics the event should address.]\n\nDesign the complete programme for the hospitality conference described. Include: the conference theme and the positioning statement that makes delegates feel this is the most relevant event in the sector this year, the keynote speaker brief for the opening and closing addresses (the question each keynote must answer, the profile of speaker who could credibly answer it, and the format — solo talk, fireside chat, or debate), the session architecture for Day 1 and Day 2 (the mix of formats: panel, workshop, case study, debate, rapid-fire presentations — and why this mix serves the learning objectives better than an all-panel format), 8 specific session titles and 2-sentence descriptions that would compel the target delegate to book, the networking programme design (the structured interaction formats that replace 'coffee and standing around'), the delegate take-home: the one framework or tool every attendee receives that they can use in their property on Monday morning, and the social programme for the evening of Day 1.","tags":["events","hospitality","education"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

    {"id":"hsp-93","title":"Hotel Ancillary Revenue Strategy","prompt":"Develop a comprehensive ancillary revenue strategy for a 155-room resort hotel that currently generates 82% of total revenue from rooms and only 18% from non-room sources (F&B, spa, activities, retail). The general manager's target is to grow non-room revenue to 30% of total (approximately €680,000 incremental) without adding significant fixed cost. Build the strategy across 6 revenue streams: (1) F&B — the in-room dining redesign to increase capture rate from the current 12% to 22% of guests, (2) Spa — the day guest strategy to generate revenue from non-hotel-resident locals, (3) Experiences and activities — design 5 bookable experiences that leverage the resort's natural setting, priced at €45-180 per person, (4) Retail — the curated local product retail concept that generates €85K per year from a 20 sqm retail space, (5) Meeting space — the day-use strategy for local businesses who need meeting space without staying overnight, (6) Parking and transport — the private transfer and electric bike hire program. For each stream provide the revenue target, the pricing, the investment required, and the operational owner.","tags":["revenue-management","hotels","strategy"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

    {"id":"hsp-94","title":"Restaurant PR and Media Relations Strategy","prompt":"Design a 12-month PR and media relations strategy for a new 50-cover contemporary Japanese restaurant opening in a competitive city market. The restaurant has a former Michelin-starred chef, an architectural interior worth photographing, and a sake program that is the most extensive in the country. The PR budget is €24,000 for the year. Build: the pre-opening phase (months minus-3 to 0 — the exclusive soft launch for 12 food journalists and critics, the press kit design, the photography brief for 8 key images, the embargo strategy), the opening burst (the press release, the pitch angles for different media — food press, lifestyle, architecture, drinks — and the follow-up call strategy), the ongoing media relations calendar (the 6 'news hooks' through the year that justify re-pitching to media who covered the opening), the critic relationship management (the process for identifying the 5 most influential critics and ensuring they have the optimal experience), the digital PR strategy (the food blogger programme, the UGC strategy for Instagram, the podcast outreach), and the award submission strategy. Track progress against the KPI of generating €180,000 in earned media value by end of Year 1.","tags":["marketing","restaurant","pr"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

    {"id":"hsp-95","title":"Hotel Front Office Operations Manual","prompt":"Write a comprehensive front office operations manual for a 4-star hotel with 140 rooms and a front desk team of 12 (including night audit). The manual should be practical enough to hand to a new front desk agent on Day 1 and serve as the reference guide for experienced staff handling non-routine situations. Cover: the check-in procedure (step-by-step from guest arrival at door to escorted to room — define every verification step, the credit card pre-authorization amount and procedure, the room key programming and handover, and the personalization moment that turns a transaction into a welcome), the check-out procedure (the express checkout option, the bill dispute resolution script, the luggage storage process), the reservation management section (the rate plan and restriction decision tree, how to handle walk-ins when sold out including the walk procedure and compensation standard), the telephone etiquette standards (4-ring maximum, opening script, transfer protocol, message-taking format), the shift handover template, and the top 20 non-routine situation handling guides (e.g., guest has lost passport, guest is intoxicated, guest refuses to pay, guest claims room was robbed).","tags":["operations","hotels","training"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

    {"id":"hsp-96","title":"Food and Beverage Director 100-Day Plan","prompt":"You have just been appointed as Food and Beverage Director of a 220-room full-service hotel with 3 outlets (a 110-cover signature restaurant, a 45-seat bar and lounge, and a banqueting department handling 120 events per year). Total F&B revenue is €3.4M with a departmental margin of 9% against an industry target of 18-22%. Design your complete 100-day plan. Days 1-30: Diagnosis phase — define the listening tour schedule, the financial data you need from the controller by Day 3, the guest feedback analysis, the team 1-on-1s, and the mystery diner visits you commission. Days 31-60: Priority setting phase — identify the 3 highest-impact changes from your diagnosis, build the business cases, and secure GM and owner alignment. Days 61-100: Execution phase — begin implementing the 3 priority changes, define the weekly dashboard you will use to track results, and present the 12-month roadmap to the ownership. For each phase list the deliverables, the stakeholder communications required, and the personal leadership behaviors you will model to build credibility with your team.","tags":["f&b","management","hotels"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

    {"id":"hsp-97","title":"Hospitality Management Consulting Engagement Framework","prompt":"[Describe the hospitality client engagement — the property type, the size, the presenting problem or opportunity, and the outcome the client wants to achieve.]\n\nDesign the complete consulting engagement framework for the client situation described. Cover: the diagnostic phase (the data collection protocol — which reports to request before the first site visit, the site visit observation agenda for Day 1 and Day 2, the stakeholder interview list and the 5 questions to ask each stakeholder that surface the real problem behind the presenting symptom), the analysis framework (how to structure the findings across operational, financial, competitive, and organizational dimensions), the hypothesis testing approach (how to move from observations to a causal diagnosis without over-indexing on the most vocal stakeholder's view), the recommendation structure (how to present a prioritized set of recommendations with financial impact, effort required, and organizational readiness for each), the implementation support model (the consultant's role during execution — when to advise, when to coach, when to deliver directly), and the success measurement framework (the KPIs and the frequency of progress reviews). Include the client communication cadence from kick-off to final report.","tags":["consulting","hospitality","strategy"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

    {"id":"hsp-98","title":"Hotel Pre-Opening Master Plan","prompt":"You are the pre-opening General Manager of a new 105-room lifestyle hotel opening in 9 months. The property is still under construction. Design the complete pre-opening master plan. Structure it in three phases: Phase 1 (Months 9-6 before opening): Team structure and recruitment plan for all 68 positions with priority hire sequence, PMS and technology procurement and configuration timeline, brand standards documentation, supplier contracts for food, beverage, linen, and amenities. Phase 2 (Months 5-3 before opening): Training programme design and delivery calendar starting with department heads, creation of the full SOPs library (priority order: front office, housekeeping, F&B, security), outlet concept finalization and menu development, pre-opening marketing launch (website live, social media commencement, OTA listing creation, PR campaign). Phase 3 (Months 2-0 before opening): Soft opening programme (3 weeks of invited guest stays with daily debriefs), defect snagging log and sign-off process, staff familiarization stays, opening night event design. Define the critical path item in each phase whose delay would push the opening date, and the contingency for each.","tags":["hotels","pre-opening","operations"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":true},

    {"id":"hsp-99","title":"Tourism Policy and Destination Management Framework","prompt":"Act as a destination management consultant advising a regional government. The region receives 2.8 million visitors per year, generating €1.1B in tourism revenue and 18,000 jobs. However, tourism is highly concentrated in 3 months of the year, heavily focused on 2 coastal towns (which have serious over-tourism symptoms — overtaxed infrastructure, resident resentment, environmental degradation), and shows declining visitor satisfaction scores driven by overcrowding. Design a 5-year destination management framework that addresses the concentration problem. Cover: the visitor dispersal strategy — identifying 4 under-visited inland areas with genuine tourism potential and the investment required to activate them, the demand management tools for the overcrowded hot spots (timed entry systems, dynamic visitor taxes, marketing blackout periods), the seasonal extension strategy — 3 demand-generating initiatives that incentivize visits in months October through March, the resident sentiment monitoring program and the community benefit sharing model that rebuilds social license for tourism, and the governance model that gives the destination management organization the authority and funding to implement the framework. Set 3-year and 5-year KPIs for each objective.","tags":["tourism","policy","destination-management"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":true},

    {"id":"hsp-100","title":"The Future of Hospitality — Strategic Foresight Report","prompt":"Act as a strategic foresight consultant specializing in hospitality and tourism. Write a comprehensive 2030-2040 foresight report for hospitality industry leaders. The report should be grounded in current megatrends and their second-order effects, not science fiction. Structure it around 5 forces reshaping the industry: (1) Climate adaptation — how extreme weather, rising sea levels, and temperature shifts will redraw the global tourism map, which current destination categories face existential risk, and which new cold-latitude destinations will emerge as beneficiaries; (2) AI and automation — the honest assessment of which hospitality jobs will be automated by 2035, which will be augmented, and which new roles will emerge, with implications for the talent pipeline and the trade school curriculum; (3) Experience economy maturation — the shift from Instagram-worthy moments to genuine transformation, how luxury will be redefined by the ultra-wealthy of the next decade, and the death of the generic branded hotel as a viable business model; (4) Geopolitical reordering — the new source markets as Asian and African middle classes grow, the impact of travel friction (visas, air connectivity, political volatility) on destination choice; (5) Ownership model evolution — the rise of asset-light models, fractional ownership, and community-owned lodges. For each force identify the 3 strategic implications for a hotel group deciding on investment priorities today.","tags":["future","hospitality","strategy"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":true}
];
  __exports.hospitalityPrompts = hospitalityPrompts;
})();
